import{_ as a,o,c as r,a2 as t}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E7%95%8C%E9%9D%A2.BjJx907L.png",p="/newx-doc/assets/%E8%A1%A8%E7%BB%93%E6%9E%84.CgcOy5G5.png",i="/newx-doc/assets/%E5%85%B3%E6%B3%A8%E5%9B%9E%E5%A4%8D.BHAIAjdw.png",s="/newx-doc/assets/%E6%B6%88%E6%81%AF%E5%9B%9E%E5%A4%8D.DR_IB12C.png",b=JSON.parse('{"title":"自动回复","description":"","frontmatter":{},"headers":[],"relativePath":"mp/auto-reply.md","filePath":"mp/auto-reply.md","lastUpdated":null}'),u={name:"mp/auto-reply.md"};function d(m,e,n,c,_,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="自动回复" tabindex="-1">自动回复 <a class="header-anchor" href="#自动回复" aria-label="Permalink to &quot;自动回复&quot;">​</a></h1><p>本章节，讲解自动回复的相关内容，对应 [公众号管理 -&gt; 自动回复] 菜单。如下图所示：</p><p><img src="'+l+'" alt="自动回复"></p><p>在用户关注、发送消息时，公众号可以自动回复消息给用户。</p><h2 id="_1-表结构" tabindex="-1">1. 表结构 <a class="header-anchor" href="#_1-表结构" aria-label="Permalink to &quot;1. 表结构&quot;">​</a></h2><p>自动回复对应 <code>mp_auto_reply</code> 表，结构如下图所示：</p><p><img src="'+p+'" alt="自动回复表结构"></p><p><code>type</code> 字段：回复类型，</p><ul><li>1 - 关注回复：用户关注公众号时</li><li>3 - 关键字回复：消息类型为文本时，匹配到关键字</li><li>2 - 消息回复：没有匹配到关键字时，根据消息类型</li></ul><h2 id="_2-自动回复界面" tabindex="-1">2. 自动回复界面 <a class="header-anchor" href="#_2-自动回复界面" aria-label="Permalink to &quot;2. 自动回复界面&quot;">​</a></h2><ul><li>前端：<a href="https://github.com/yudaocode/yudao-ui-admin-vue2/blob/master/src/views/mp/autoReply/index.vue" target="_blank" rel="noreferrer">/@views/mp/autoReply</a></li><li>后端：<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/message/MpAutoReplyController.java" target="_blank" rel="noreferrer">MpAutoReplyController</a></li></ul><h2 id="_3-关注回复" tabindex="-1">3. 关注回复 <a class="header-anchor" href="#_3-关注回复" aria-label="Permalink to &quot;3. 关注回复&quot;">​</a></h2><p>用户关注公众号时，被动回复用户消息，由 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/message/MpAutoReplyServiceImpl.java#L181-L200" target="_blank" rel="noreferrer">MpAutoReplyServiceImpl</a> 的 <code>replyForSubscribe</code> 方法来生成回复内容。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+i+'" alt="关注回复"></p><h2 id="_4-消息回复-关键字回复" tabindex="-1">4. 消息回复 &amp; 关键字回复 <a class="header-anchor" href="#_4-消息回复-关键字回复" aria-label="Permalink to &quot;4. 消息回复 &amp; 关键字回复&quot;">​</a></h2><p>用户发送消息给公众号时，自动回复消息给用户，分为两种情况：</p><ul><li>关键字回复：消息类型为文本时，匹配到关键字，自动回复消息</li><li>消息回复：没有匹配到关键字时，根据消息类型，自动回复消息</li></ul><p>这两种情况，由 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/message/MessageAutoReplyHandler.java" target="_blank" rel="noreferrer">MessageAutoReplyHandler</a> 调用 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/message/MpAutoReplyServiceImpl.java#L154-L179" target="_blank" rel="noreferrer">MpAutoReplyServiceImpl</a> 的 <code>replyForMessage</code> 方法来生成回复内容。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+s+'" alt="消息回复"></p>',21)])])}const g=a(u,[["render",d]]);export{b as __pageData,g as default};
